import React, { useRef } from 'react';
import { useMountEffect } from 'primereact/hooks';
import { Messages } from 'primereact/messages';

export default function Closable() {
    const msgs = useRef(null);
    
    useMountEffect(() => {
        if (msgs.current) {
            msgs.current.clear();
            msgs.current.show([
                { sticky: true, className: 'success', summary: 'Success', detail: 'Closable Message' },
                { sticky: true, className: 'info', summary: 'Info', detail: 'Not Closable Message', closable: false }
            ]);
        }
    });

    return (
        <div className="card">
            <Messages ref={msgs} />
        </div>
    )
}